# Media Catalog Windows VLC protocol installer.
# Generated by the catalog with an allowlist of its configured SMB hosts.

[CmdletBinding()]
param()

$ErrorActionPreference = 'Stop'

function Find-VlcExecutable {
    $registryKeys = @(
        'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\App Paths\vlc.exe',
        'Registry::HKEY_LOCAL_MACHINE\Software\Microsoft\Windows\CurrentVersion\App Paths\vlc.exe'
    )
    foreach ($keyPath in $registryKeys) {
        if (Test-Path -LiteralPath $keyPath) {
            $candidate = (Get-Item -LiteralPath $keyPath).GetValue('')
            if ($candidate -and (Test-Path -LiteralPath $candidate)) { return $candidate }
        }
    }

    $candidates = @()
    if ($env:ProgramFiles) {
        $candidates += (Join-Path $env:ProgramFiles 'VideoLAN\VLC\vlc.exe')
    }
    if (${env:ProgramFiles(x86)}) {
        $candidates += (Join-Path ${env:ProgramFiles(x86)} 'VideoLAN\VLC\vlc.exe')
    }
    foreach ($candidate in $candidates) {
        if (Test-Path -LiteralPath $candidate) { return $candidate }
    }
    return $null
}

$VlcPath = Find-VlcExecutable
if (-not $VlcPath) {
    throw 'VLC was not found. Install the desktop VLC from videolan.org, then run this setup again.'
}

$InstallDirectory = Join-Path ([Environment]::GetFolderPath('LocalApplicationData')) 'MediaCatalog'
$HandlerPath = Join-Path $InstallDirectory 'OpenInVlc.ps1'
New-Item -ItemType Directory -Path $InstallDirectory -Force | Out-Null

$HandlerSource = @'
[CmdletBinding()]
param(
    [Parameter(Mandatory = $true, Position = 0)]
    [string]$ProtocolUri
)

$ErrorActionPreference = 'Stop'
$AllowedSmbHosts = __ALLOWED_SMB_HOSTS__

function Find-VlcExecutable {
    $registryKeys = @(
        'Registry::HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\App Paths\vlc.exe',
        'Registry::HKEY_LOCAL_MACHINE\Software\Microsoft\Windows\CurrentVersion\App Paths\vlc.exe'
    )
    foreach ($keyPath in $registryKeys) {
        if (Test-Path -LiteralPath $keyPath) {
            $candidate = (Get-Item -LiteralPath $keyPath).GetValue('')
            if ($candidate -and (Test-Path -LiteralPath $candidate)) { return $candidate }
        }
    }

    $candidates = @()
    if ($env:ProgramFiles) {
        $candidates += (Join-Path $env:ProgramFiles 'VideoLAN\VLC\vlc.exe')
    }
    if (${env:ProgramFiles(x86)}) {
        $candidates += (Join-Path ${env:ProgramFiles(x86)} 'VideoLAN\VLC\vlc.exe')
    }
    foreach ($candidate in $candidates) {
        if (Test-Path -LiteralPath $candidate) { return $candidate }
    }
    return $null
}

try {
    $requestUri = [Uri]$ProtocolUri
} catch {
    exit 2
}
if (-not $requestUri.IsAbsoluteUri -or $requestUri.Scheme -ne 'media-catalog-vlc' -or $requestUri.Host -ne 'play') {
    exit 3
}

$payload = $requestUri.AbsolutePath.Trim('/')
if (-not $payload -or $payload -notmatch '^[A-Za-z0-9_-]+$') {
    exit 4
}
switch ($payload.Length % 4) {
    0 { }
    2 { $payload += '==' }
    3 { $payload += '=' }
    default { exit 5 }
}

try {
    $base64 = $payload.Replace('-', '+').Replace('_', '/')
    $target = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($base64))
    $networkUri = [Uri]$target
} catch {
    exit 6
}
if (-not $networkUri.IsAbsoluteUri -or $networkUri.Scheme -ne 'smb') {
    exit 7
}
if ($target -match '[\s"]') {
    exit 7
}
if ($AllowedSmbHosts -notcontains $networkUri.IdnHost.ToLowerInvariant()) {
    exit 8
}

$VlcPath = Find-VlcExecutable
if (-not $VlcPath) {
    exit 9
}

Start-Process -FilePath $VlcPath -ArgumentList @($target)
'@

$Utf8NoBom = New-Object System.Text.UTF8Encoding($false)
[IO.File]::WriteAllText($HandlerPath, $HandlerSource, $Utf8NoBom)

$SchemeRoot = 'Registry::HKEY_CURRENT_USER\Software\Classes\media-catalog-vlc'
$CommandKey = Join-Path $SchemeRoot 'shell\open\command'
$IconKey = Join-Path $SchemeRoot 'DefaultIcon'
foreach ($keyPath in @(
    $SchemeRoot,
    $IconKey,
    (Join-Path $SchemeRoot 'shell'),
    (Join-Path $SchemeRoot 'shell\open'),
    $CommandKey
)) {
    New-Item -Path $keyPath -Force | Out-Null
}
Set-Item -Path $SchemeRoot -Value 'URL:Media Catalog VLC'
New-ItemProperty -Path $SchemeRoot -Name 'URL Protocol' -Value '' -PropertyType String -Force | Out-Null
Set-Item -Path $IconKey -Value ('"{0}",0' -f $VlcPath)

$PowerShellPath = Join-Path $PSHOME 'powershell.exe'
$Command = '"{0}" -NoProfile -NonInteractive -WindowStyle Hidden -ExecutionPolicy Bypass -File "{1}" "%1"' -f $PowerShellPath, $HandlerPath
Set-Item -Path $CommandKey -Value $Command

Write-Host ''
Write-Host 'Media Catalog VLC handoff installed for this Windows user.' -ForegroundColor Green
Write-Host ('Allowed SMB hosts: ' + ((__ALLOWED_SMB_HOSTS__) -join ', '))
Write-Host 'Return to the catalog and choose VLC here.'
